'use strict';
const phaseOf=d=>d.id===1?'出发 · 芬兰':d.id<=9?'挪威 · 北境海岸':d.id<=15?'冰岛 · 环南岸':d.id===16?'丹麦 · 哥本哈根':'返程 · 赫尔辛基与北京';
const representative=d=>selectedSpots(d).find(k=>pImage(k))||({1:'station',2:'tromso',8:'ballstad',9:'oslo',17:'station'})[d.id]||'';
const highlights=d=>selectedSpots(d).map(k=>DATA.places[k]?.name).filter(Boolean).slice(0,4);
let browseCountry=state.browseCountry||'all',browseSearch=state.browseSearch||'',toolCategory=state.toolCategory||'activities',toolDay=state.toolDay||'all';
const toolNames={activities:'活动预订',flights:'航班及交通',hotels:'酒店与地址',roads:'天气与道路',transport:'自驾与停车',emergency:'应急信息',lists:'行李与采购',offline:'离线资料'};
function dateControl(label='选择日期'){return `<button class="date-control" data-dates>${ico('calendar')}<span>${label}</span><span>⌄</span></button>`;}
function dayPagination(d){return `<nav class="day-pagination" aria-label="切换行程日期"><button data-day="${d.id-1}" ${d.id===1?'disabled':''}>← 前一天</button><button data-view="itinerary">全部行程</button><button data-day="${d.id+1}" ${d.id===18?'disabled':''}>后一天 →</button></nav>`;}
function dateRows(mapMode=false){const today=tripToday(new Date(),DATA.days,tripCalendarChanges);return DATA.days.map(d=>`<button class="date-option ${d.id===(mapMode?+mapFilter:state.day)?'selected':''}" data-${mapMode?'mapday':'day'}="${d.id}" ${d.id===(mapMode?+mapFilter:state.day)?'aria-current="date"':''}><strong>${shortDate(d.date)}</strong><span>${esc(d.title)}<small>${esc(d.region)}</small></span><em>${today.inTrip&&today.day===d.id?'今天':d.id===(mapMode?+mapFilter:state.day)?'查看中':''}</em></button>`).join('');}
function compactDays(filter=browseSearch,region=browseCountry){let phase='';const t=tripToday(new Date(),DATA.days,tripCalendarChanges),q=filter.toLocaleLowerCase();return DATA.days.filter(d=>(region==='all'||(region==='transfer'?!['挪威','冰岛'].includes(d.region):d.region===region))&&(!q||[d.title,d.region,d.date,highlights(d).join(' '),...(d.flights||[]).flat()].join(' ').toLocaleLowerCase().includes(q))).map(d=>{const group=phaseOf(d),head=group!==phase?`<h2 class="phase-title">${group}</h2>`:'';phase=group;const key=representative(d),src=smallPhoto(key);return head+`<article class="compact-day"><button class="compact-day-main" data-day="${d.id}"><span class="compact-date"><strong>${shortDate(d.date)}</strong><small>${new Intl.DateTimeFormat('zh-CN',{weekday:'short',timeZone:'UTC'}).format(new Date(d.date+'T12:00:00Z'))}</small>${t.inTrip&&t.day===d.id?'<em>今天</em>':''}</span><span class="compact-copy"><strong>${esc(d.title)}</strong><small>${esc(highlights(d).slice(0,3).join(' · ')||(d.flights||[]).map(f=>f[0]+' '+f[1]+'→'+f[4]).join(' · ')||d.region)}</small><span>${d.flights?.length?'航班 · ':''}${d.hotel?'住宿 · ':''}${DATA.bookings.some(b=>b.day===d.id)?'已订活动 · ':''}第${d.id}天${d.id===state.day?' · 查看中':''}</span></span>${src?`<img src="${src}" width="96" height="96" alt="${esc(DATA.places[key]?.name)}" loading="lazy" decoding="async">`:'<span class="compact-air">'+ico('plane')+'</span>'}</button></article>`;}).join('')||'<p class="empty-state">没有匹配的日期或目的地。试试“冰河湖”或“10-30”。</p>';}
function itineraryView(){return `<header class="utility-header"><p class="editor-label">18 OCT — 04 NOV 2026</p><h1>全部行程</h1><div class="segments country-segments" role="group" aria-label="筛选国家">${[['all','全部'],['挪威','挪威'],['冰岛','冰岛'],['transfer','途经城市']].map(([k,n])=>`<button data-country-filter="${k}" aria-pressed="${browseCountry===k}">${n}</button>`).join('')}</div><label class="destination-search">${ico('pin')}<input id="destinationSearch" type="search" value="${esc(browseSearch)}" placeholder="目的地、日期或航班" aria-label="搜索行程"></label><p class="search-count" id="searchCount" role="status">按真实旅程顺序排列</p></header><div id="compactIndex">${compactDays()}</div>`;}
function routeOverview(){return `<section class="home-route"><div><p class="editor-label">挪威与冰岛 · 经芬兰、丹麦</p><h2>一路向北，再到冰与火之地。</h2><p class="route-sentence">北京 → 赫尔辛基 → 特罗姆瑟 → 罗弗敦 → 博德 → 奥斯陆 → 冰岛 → 哥本哈根 → 赫尔辛基 → 北京</p><p class="experience-line">观鲸 · 峡湾海岸 · 温泉 · 冰河湖 · 蓝冰洞 · Silfra浮潜</p><p class="info-caption">追光与见鲸均受自然条件影响。</p><button class="action-button" data-mapday="all">查看全程路线 ↗</button></div><button class="home-atlas" data-mapday="all" aria-label="打开路线总览">${atlas()}</button></section>`;}
function home(){const t=tripToday(new Date(),DATA.days,tripCalendarChanges);if(t.inTrip){state.day=t.day;return dayView(true);}const before=t.boundary==='first',days=Math.max(0,Math.ceil((Date.parse(DATA.days[0].date+'T00:00:00+08:00')-Date.now())/86400000)),f=DATA.days[0].flights[0],left=packing.filter((_,i)=>!state.checks['packing-'+i]).length;return `<section class="journal-hero"><img src="${pImage('hamnoy')}" width="1176" height="805" alt="Hamnøy红屋与罗弗敦山海" fetchpriority="high" decoding="async"><div class="hero-copy"><p>2026.10.18 — 11.04 · 18天</p><h1>Nordic<br>Journal <em>2026</em></h1><p>挪威 · 冰岛</p><button class="hero-entry" data-view="itinerary">${before?'浏览旅行日程':'回顾十八天'} →</button></div><span class="hero-caption">Hamnøy · Lofoten, Norway</span></section><section class="home-dashboard ${before?'before-trip':'after-trip'}"><header><p class="editor-label">${before?'行前准备':'旅程回顾'}</p><h2>${before?'距出发 '+days+' 天':'这段旅程已结束'}</h2></header>${before?`<div class="departure-plan"><div><p>首段航班 · 10月18日</p><h3>${esc(f[0])} · ${esc(f[1])} → ${esc(f[4])}</h3><p><strong>北京 ${esc(f[3])} 起飞</strong> · 赫尔辛基 ${esc(f[6])} 抵达</p><p class="info-caption">均为当地时间。四件行李额度及手续向航司核对；原路书未指定大兴报到时间。</p><button class="small-link" data-day="1">查看出发当天安排 →</button></div><div class="prep-checks"><h3>行前检查 <small id="prepCount">${left} 项未勾选</small></h3><p class="info-caption">勾选只保存在这台设备，不代表预订已完成。</p>${checklist('packing',packing)}<div class="inline-actions"><button data-detail="groceries">采购清单</button><button data-offline>保存离线资料</button></div></div></div><p class="departure-reminder">首日抵达后先入境取箱、入住存箱，再按出发窗口选择休息或夜游；不能省略这些步骤。</p>`:`<div class="recap-photos">${['hamnoy','jokulsarlon','cave'].map(k=>photoCard(k,0)).join('')}</div><button class="action-button" data-view="itinerary">查看完整日程 →</button>`}${routeOverview()}</section><footer class="journal-footer"><span>Nordic Journal 2026</span><div><button data-credits>照片来源与许可</button><button data-top>回到顶部 ↑</button><a href="essentials.html">精简资料页 ↗</a></div></footer>`;}
function bookingQuick(b){const d=DATA.days[b.day-1];return `<article class="quick-booking"><p class="editor-label">${shortDate(d.date)} · 已订 ${b.people} 位</p><h3>${esc(b.name)}</h3><p>${esc(b.time)} · <strong>报到目标 ${esc(b.report)}</strong></p><p>${esc(b.place)}</p><div class="inline-actions"><button data-day="${b.day}" data-focus-step="${bookingRow(d,b)}">打开对应安排 →</button><button data-booking="${b.day}">预订说明</button>${ext(navLink(DATA.places[b.meeting||b.spot]),'集合点导航','primary-link')}</div></article>`;}
function hotelQuick(d){const h=DATA.hotels[d.hotel];return !h?'':`<div class="inline-stay" id="todayStay"><h3>${esc(h.cn)}</h3><p>${esc(h.name)}<br>${esc(h.address)}</p><p class="info-caption">${esc(h.note)}</p><div class="inline-actions">${ext(hotelLink(d.hotel),'酒店导航','primary-link')}<button data-hotel="${d.hotel}">住宿详情</button><button data-copy="${esc(h.name+'\n'+h.address)}">复制地址</button></div></div>`;}
function stayRow(d,rows){if(!d.hotel)return -1;let i=rows.findIndex(r=>/入住|寄存/.test(r.stepTitle||''));if(i<0)i=rows.map((r,i)=>({r,i})).reverse().find(x=>/酒店|公寓|Hali|回房|休息/.test(x.r.text))?.i;return i??rows.length-1;}
function routeChoice(d){return d.variants?`<div class="route-choice"><div class="choice" role="group" aria-label="路线选择">${Object.entries(d.variants).map(([k,v])=>`<button data-variant="${k}" aria-pressed="${(state.variants[d.id]||'A')===k}"><b>${k}</b><span>${esc(v.label)}</span></button>`).join('')}</div><div class="plan-confirm"><span id="planChoiceStatus">${state.confirmed?.[d.id]===(state.variants[d.id]||'A')?'已确认本机方案':'暂选方案，尚未确认'}</span><button data-confirm-plan>${state.confirmed?.[d.id]===(state.variants[d.id]||'A')?'取消确认':'确认此方案'}</button></div><div id="transportOptions">${d.id===1&&state.variants[1]==='B'?transportBox():''}</div></div>`:'';}
function timeCard(d,now=new Date()){const rows=selectedPlan(d),pos=planPosition(d,now,rows);if(!pos.live){const booking=DATA.bookings.find(b=>b.day===d.id);return `<div class="day-preview">${booking?`<p><strong>${esc(booking.report)} 报到目标 · ${esc(booking.name)}</strong></p>`:''}<p>计划预览 · ${highlights(d).slice(0,3).map(esc).join(' · ')||esc(d.title)}</p><p class="info-caption">当前不是这一天，不显示过期或尚未到来的“下一项”。</p></div>`;}const index=pos.current>=0?pos.current:pos.approximate>=0?pos.approximate:pos.next,r=rows[index];if(!r)return '<p class="info-caption">已无后续明确时刻，晚间或活动结束后的安排见下方时间线。</p>';const b=DATA.bookings.find(b=>b.day===d.id),keys=(r.nav||[]).filter(k=>!k.startsWith('hotel:'));return `<section class="action-now"><div><p class="editor-label">${pos.current>=0?'当前计划时段':pos.approximate>=0?'预计安排 · 时间有弹性':'下一项计划'} · 当地时间</p><h2>${esc(r.stepTitle)}</h2><strong>${esc(r.time)}</strong>${r.critical?`<p>${esc(r.critical)}</p>`:''}${b&&rows.findIndex(x=>x.time.includes(b.report))>=index?`<p>已订活动 · ${esc(b.report)} 报到目标</p>`:''}${pos.current>=0&&pos.next>=0?`<p class="following-plan">随后 ${esc(rows[pos.next].time)} · ${esc(rows[pos.next].stepTitle)}</p>`:''}</div><div class="inline-actions">${keys.length?ext(navPoint(keys[0]).url,'下一地点导航','primary-link'):b?ext(navLink(DATA.places[b.meeting||b.spot]),'集合点导航','primary-link'):''}<button data-step-focus="${index}">查看此项 ↓</button></div><small>按原计划提示；不代表实际开始或完成。</small></section>`;}
function bookingInline(b){const p=DATA.places[b.meeting||b.spot];return `<aside class="action-booking"><p><strong>已订 ${b.people} 位 · ${esc(b.report)} 报到目标</strong><br>${esc(b.name)} · ${esc(b.time)}</p><p>${esc(b.place)}</p><p>${esc(b.walk)}</p><p class="info-caption">${esc(b.note)}</p><div class="inline-actions">${ext(navLink(p),'集合点导航','primary-link')}${b.parking?ext(navLink(DATA.places[b.parking]),'停车场导航','small-link'):''}<button data-booking="${b.day}">预订详情</button></div></aside>`;}
function renderTimeline(d){const rows=selectedPlan(d),pos=planPosition(d),stay=stayRow(d,rows);return `<div class="timeline">${rows.map((r,i)=>{const b=DATA.bookings.find(b=>b.day===d.id&&bookingRow(d,b,rows)===i);return `<article id="step-${i}" class="timeline-row ${r.critical?'time-critical':''} ${pos.current===i?'is-current':pos.next===i?'is-next':''}" ${pos.current===i?'aria-current="step"':''}><div class="timeline-time">${inline(r.time)}${/CZ8171/.test(r.text)?'<small>北京 → 赫尔辛基当地时间</small>':''}</div><div class="timeline-text"><div class="timeline-heading"><h3 class="step-title">${esc(r.stepTitle||'计划安排')}</h3><span class="step-state">${pos.current===i?'当前计划':pos.next===i?'下一项':''}</span></div><p class="step-description">${inline(r.text)}</p>${r.critical?`<p class="critical-note">${esc(r.critical)}</p>`:''}${b?bookingInline(b):''}${i===stay?hotelQuick(d):''}<div class="step-locations">${(r.nav||[]).filter(k=>!k.startsWith('hotel:')).map(k=>`<button data-step-map="${i}" data-map-key="${k}">${esc(DATA.places[k]?.name||k)} · 地图 ↗</button>`).join('')}${!b&&i!==stay&&(r.nav||[]).length?`<button data-navigation="${r.nav[0]}">导航 ↗</button>`:''}</div></div></article>`;}).join('')}</div>`;}
function extraDay(d){const k=representative(d),src=pImage(k);return `${src?`<section class="day-photography"><button class="summary-image" data-photo="${k}" aria-label="全屏查看${esc(DATA.places[k]?.name)}"><img src="${src}" ${photoAttributes(src)} width="1200" height="800" alt="${esc(DATA.places[k]?.name)}" loading="lazy"><span>查看照片 ⤢</span></button><p class="sun-summary">日出约 ${esc(d.sun[0])} · 日落约 ${esc(d.sun[1])}</p></section>`:''}${selectedSpots(d).filter(k=>pImage(k)).length?section('沿途风景','',routeBoard(selectedSpots(d).filter(k=>pImage(k)),d.id)):''}<div class="expand-group"><button data-expand="notes" aria-expanded="false" aria-controls="notesPanel">备选安排与完整攻略 <span>⌄</span></button><div id="notesPanel" class="expand-panel" inert><div><div class="rich">${d.alert?'<p>'+inline(d.alert)+'</p>':''}${daySupplement()}${markdown(d.notes||'')}</div></div></div></div>`;}
function dayView(isToday=false){const t=tripToday(new Date(),DATA.days,tripCalendarChanges),d=DATA.days[state.day-1];return `<header class="utility-header day-utility"><p class="editor-label">${dateText(d.date)} · ${esc(d.region)} · 第${d.id}天</p><h1>${esc(d.title)}</h1><div class="day-clock"><span>${isToday?'计划所在地':'此日目的地'} · <time data-clock-zone="${isToday?t.zone:d.tz}"></time></span><small>当前当地时间</small></div><div class="utility-actions">${dateControl('切换日期')}<button data-mapday="${d.id}">当天路线 ↗</button>${d.hotel?'<button data-scroll-id="todayStay">今晚住宿 ↓</button>':''}</div></header><div id="planNow">${timeCard(d)}</div>${routeChoice(d)}<section class="section day-timeline"><div class="section-top"><h2>行动时间线</h2></div><div id="planTimeline">${renderTimeline(d)}</div></section><div id="dayExtras">${extraDay(d)}</div>${dayPagination(d)}`;}
function toolFilter(){return `<label class="tool-date-filter">日期筛选 <select id="toolDate" aria-label="筛选工具箱日期"><option value="all">全部日期</option>${DATA.days.map(d=>`<option value="${d.id}" ${toolDay===String(d.id)?'selected':''}>${shortDate(d.date)} · ${esc(d.title)}</option>`).join('')}</select></label>`;}
function toolboxView(){return `<header class="utility-header"><p class="editor-label">FIELD TOOLS</p><h1>工具箱</h1></header><nav class="tool-categories" aria-label="工具分类">${Object.entries(toolNames).map(([k,n])=>`<button data-tool="${k}" aria-pressed="${toolCategory===k}">${n}</button>`).join('')}</nav><section class="tool-panel"><header class="tool-panel-head"><h2 id="toolTitle">${toolNames[toolCategory]}</h2><div id="toolFilter">${['activities','flights','hotels'].includes(toolCategory)?toolFilter():''}</div></header><div id="toolContent">${toolBody(toolCategory)}</div></section>`;}
function toolBody(k){const days=toolDay==='all'?DATA.days:DATA.days.filter(d=>d.id===+toolDay);if(k==='activities')return DATA.bookings.filter(b=>days.some(d=>d.id===b.day)).map(bookingQuick).join('')||'<p class="empty-state">原路书没有这一天的已订活动。温泉建议预约属于暂定方案。</p>';if(k==='flights')return days.filter(d=>d.flights?.length).map(d=>`<h3>${dateText(d.date)}</h3><div class="flights">${d.flights.map(flight).join('')}</div><button class="small-link" data-day="${d.id}">当天交通安排 →</button>`).join('')||'<p class="empty-state">原路书这一天没有航班。</p>';if(k==='hotels')return [...new Set(days.map(d=>d.hotel).filter(Boolean))].map(key=>{const h=DATA.hotels[key];return `<article class="tool-hotel"><p class="editor-label">${DATA.days.filter(d=>d.hotel===key).map(d=>shortDate(d.date)).join(' / ')}</p>${hotelButton(key)}<p>${esc(h.address)}</p>${ext(hotelLink(key),'酒店导航','primary-link')}</article>`;}).join('')||'<p>这一天没有安排住宿。</p>';if(k==='transport')return `<details class="tool-disclosure"><summary>赫尔辛基往返交通</summary>${helTransportDetail()}</details>${['norway','iceland'].map(r=>`<details class="tool-disclosure"><summary>${r==='norway'?'挪威':'冰岛'}自驾、停车与罚单</summary><div class="rich">${markdown(DATA.guides[r])}</div></details>`).join('')}`;if(k==='lists')return `<details class="tool-disclosure" open><summary>行李清单</summary>${checklist('packing',packing)}</details><details class="tool-disclosure"><summary>四晚厨房采购</summary>${checklist('grocery',groceries)}</details>`;if(k==='roads')return emergency().replace(/<div class="callout danger">[\s\S]*?<\/div>/,'');if(k==='emergency')return `<p class="emergency-number">挪威医疗 <a href="tel:113">113</a></p><p class="emergency-number">警方与欧盟紧急求助 <a href="tel:112">112</a></p>${emergency()}`;return offlineBody();}
photoCard=(k,i)=>{const p=DATA.places[k],src=smallPhoto(k);return !p||!src?'':`<figure class="postcard"><button class="postcard-photo" data-photo="${k}" aria-label="全屏查看${esc(p.name)}"><img src="${src}" alt="${esc(p.name)}" loading="lazy" decoding="async" width="720" height="480"></button><figcaption class="postcard-footer"><button data-place="${k}">${esc(p.name)} <span>详情 ↗</span></button></figcaption></figure>`;};
